32	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
33	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
34	    @Mapping(target = "possibleDuplicate", expression = "java(possibleDuplicate(owner))")
35	    OwnerDto toOwnerDto(Owner owner);
36	
37	    Owner toOwner(OwnerDto ownerDto);
