39	    /** Format an owner's name as 'LastName, FirstName' for display. */
40	    default String displayName(Owner owner) {
41	        return owner.getLastName() + ", " + owner.getFirstName();
42	    }
43	
44	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot. */
45	    default String initials(Owner owner) {
46	        return initial(owner.getFirstName()) + initial(owner.getLastName());
47	    }
48	
49	    private static String initial(String name) {
50	        return Character.toUpperCase(name.charAt(0)) + ".";
51	    }
52	
53	    /** The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
54	     * last two digits of the registrationDate year. */
55	    default String membershipNumber(Owner owner) {
56	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
57	            return null;
58	        }
59	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
