62	    /** The owner's membership level from 1 to 3: starts at 1, plus 1 when an email is present,
63	     * plus 1 when namesakeCount is 0, capped at 3 (level 4 is reserved for tenure). */
64	    default int membershipLevel(Owner owner) {
65	        int level = 1;
66	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
67	        if (hasEmail) {
68	            level++;
69	        }
70	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
71	            level++;
72	        }
73	        return Math.min(level, 3);
74	    }
75	
76	    /** The owner's canonical region: the REGION segment of the customer code (see
77	     * {@link CustomerCode}), or null when the customer code is unset. */
78	    default String locality(Owner owner) {
