112	    @Mapping(target = "customerCode", ignore = true)
113	    @Mapping(target = "householdId", ignore = true)
114	    @Mapping(target = "namesakeCount", ignore = true)
115	    @Mapping(target = "householdSize", ignore = true)
116	    @Mapping(target = "bulkSignupWarning", ignore = true)
